import numpy as np
from scipy.spatial.distance import cdist
L=open('frag_opt.xyz').read().split('\n')[2:]
L=[l.split() for l in L if l.strip()]
el=[l[0] for l in L];X=np.array([[float(x) for x in l[1:]] for l in L])
ru,cl,P,N=21,22,11,20
X=X-X[ru]
D=cdist(X,X)
def nbrs(i): return [j for j in range(len(el)) if j!=i and D[i,j]<(1.25 if 'H' in (el[i],el[j]) else 1.95)]
def side(P,C):
    seen={C};st=[C]
    while st:
        a=st.pop()
        for b in nbrs(a):
            if b not in (P,ru) and b not in seen: seen.add(b);st.append(b)
    return sorted(seen-{C})
tb=[c for c in nbrs(P) if el[c]=='C' and len(side(P,c))==12]
groups={c:side(P,c) for c in tb}; print({k:len(v) for k,v in groups.items()})
def rotate(X,P,C,idx,ang):
    k=X[C]-X[P];k/=np.linalg.norm(k); Y=X.copy()
    for i in idx:
        v=X[i]-X[C]; Y[i]=X[C]+v*np.cos(ang)+np.cross(k,v)*np.sin(ang)+k*(k@v)*(1-np.cos(ang))
    return Y
u=lambda v:v/np.linalg.norm(v)
z=-u(u(X[N])+u(X[P])+u(X[cl])); cen=1.72*z
a=u(np.cross(z,[1,0,0])); b=np.cross(z,a)
def arene(off):
    atoms=[]
    for k in range(6):
        t=k*np.pi/3+off; out=np.cos(t)*a+np.sin(t)*b; r=cen+1.41*out
        atoms.append(('C',r))
        if k==0:
            c=r+1.51*out+0.1*z; atoms.append(('C',c)); atoms.append(('H',c+1.09*z))
            p=np.cross(out,z)
            for s in (1,-1):
                cc=c+0.9*out+s*1.25*p-0.3*z; atoms.append(('C',cc))
                for hv in [out,s*p,z]: atoms.append(('H',cc+1.09*u(hv)))
        elif k==3:
            c=r+1.50*out+0.1*z; atoms.append(('C',c)); p=np.cross(out,z)
            for hv in [out+0.3*z,p-0.3*out+0.3*z,-p-0.3*out+0.3*z]: atoms.append(('H',c+1.09*u(hv)))
        else: atoms.append(('H',r+1.08*out+0.05*z))
    return atoms
best=None
angs=np.radians(np.arange(0,120,10))
c1,c2=tb
for a1 in angs:
  Y1=rotate(X,P,c1,groups[c1],a1)
  for a2 in angs:
    Y=rotate(Y1,P,c2,groups[c2],a2)
    lig=[i for i in range(len(el)) if i!=ru]
    for off in np.radians(np.arange(0,360,15)):
        at=arene(off); Z=np.array([p for _,p in at])
        md=cdist(Z,Y[lig]).min()
        if best is None or md>best[0]: best=(md,a1,a2,off,Y,at)
print('best min dist',best[:4])
Y,at=best[4],best[5]
allel=el+[s for s,_ in at]; allX=np.vstack([Y]+[p for _,p in at])
with open('init8.xyz','w') as f:
    f.write(f"{len(allel)}\n\n")
    for s,p in zip(allel,allX): f.write(f"{s} {p[0]:.4f} {p[1]:.4f} {p[2]:.4f}\n")
